const changed=[];
for (let i=2;i<=19;i++){
  const cell=wb.getRange('Sheet1!A'+i);
  const v=cell.getCell().getValue();
  if (typeof v==='string'){
    const t=v.search(/T.{12}Z$/);
    if (t<0) { warn('unmatched',i,v); continue; }
    const [y,m,d]=v.slice(0,t).split('-').map(Number);
    cell.setValue(Date.UTC(y,m-1,d)/86400000+25569);
    changed.push(i);
  }
}
wb.getRange('Sheet1!A2:A19').getStyle().setNumberFormat('m/dd/yyyy');
log(changed.join(','));
const out=[];
for (let i=1;i<=20;i++){const c=wb.getRange('Sheet1!A'+i).getCell(); out.push([i,c.getValue(),typeof c.getValue(),c.getText(),c.getStyle().getNumberFormat()]);}
out

